import { formatCurrency } from '@/lib/utils'
import { cn } from '@/lib/utils'

export type KPIStripData = {
  total_value_cents: number
  below_min_count: number
  pos_in_flight: number
  spent_30d_cents: number
}

interface Props {
  data: KPIStripData
}

interface KPICardProps {
  label: string
  value: string
  rustAccent?: boolean
}

function KPICard({ label, value, rustAccent = false }: KPICardProps) {
  return (
    <div
      className={cn(
        'rounded-md border border-border bg-card p-6',
        'shadow-soft',
        rustAccent && 'border-l-2 border-l-rust',
      )}
    >
      <p
        className="text-[11px] font-bold uppercase tracking-[0.08em] text-stone-brand"
        aria-label={label}
      >
        {label}
      </p>
      <p
        className="mt-2 text-[32px] font-extrabold leading-none tabular-nums text-foreground md:text-[52px]"
        aria-live="polite"
      >
        {value}
      </p>
    </div>
  )
}

export function InventoryKPIStrip({ data }: Props) {
  const belowMinValue =
    data.below_min_count === 0
      ? '0'
      : `${data.below_min_count} item${data.below_min_count === 1 ? '' : 's'}`

  return (
    <div className="grid grid-cols-2 gap-4 lg:grid-cols-4" aria-label="Inventory summary">
      <KPICard
        label="Total Stock Value"
        value={formatCurrency(data.total_value_cents)}
      />
      <KPICard
        label="Below Min"
        value={belowMinValue}
        rustAccent={data.below_min_count > 0}
      />
      <KPICard
        label="POs in Flight"
        value={String(data.pos_in_flight)}
      />
      <KPICard
        label="Spent · 30D"
        value={formatCurrency(data.spent_30d_cents)}
      />
    </div>
  )
}

import { Skeleton } from '@/components/ui/skeleton'

export function InventoryKPIStripSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4 lg:grid-cols-4" aria-hidden="true">
      {Array.from({ length: 4 }, (_, i) => (
        <div
          key={i}
          className="rounded-md border border-border bg-card p-6 shadow-soft"
          style={{ animationDelay: `${i * 60}ms` }}
        >
          {/* Label placeholder */}
          <Skeleton className="h-2.5 w-24" style={{ animationDelay: `${i * 60}ms` }} />
          {/* Number placeholder */}
          <Skeleton className="mt-3 h-9 w-28 md:h-12" style={{ animationDelay: `${i * 60}ms` }} />
        </div>
      ))}
    </div>
  )
}

