  locations: { id: string; name: string } | null
}

interface ItemsTableProps {
  viewMode?: 'table' | 'cards'
}

// ── Toggle helper — pure function, no mutation of previous Set ────────────────

function toggleId(prev: Set<string>, id: string): Set<string> {
  const next = new Set(prev)
  if (next.has(id)) {
    next.delete(id)
  } else {
    next.add(id)
  }
  return next
}

export function ItemsTable({ viewMode = 'table' }: ItemsTableProps) {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [categoryFilter, setCategoryFilter] = useState('all')
  const [stockFilter, setStockFilter] = useState('all')
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editItem, setEditItem] = useState<ItemWithRelations | null>(null)
  const [adjustItem, setAdjustItem] = useState<ItemWithRelations | null>(null)

  // ── Bulk-select state ──────────────────────────────────────────────────────
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())
  const [bulkThresholdsOpen, setBulkThresholdsOpen] = useState(false)
  const [archiveConfirmOpen, setArchiveConfirmOpen] = useState(false)

  const params = new URLSearchParams()
  if (categoryFilter !== 'all') params.set('category', categoryFilter)
  if (stockFilter !== 'all') params.set('stock_status', stockFilter)

  const { data, isLoading, error } = useQuery({
    queryKey: queryKeys.inventory.items({ category: categoryFilter, stock_status: stockFilter }),
    queryFn: async () => {
      const res = await fetch(`/api/inventory/items?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch items')
      const json = await res.json() as { data: ItemWithRelations[] }
      return json.data
    },
  })

  // Clear selection whenever filters change (items list changes underneath)
  useEffect(() => {
    setSelectedIds(new Set())
  }, [categoryFilter, stockFilter, search])

  const archiveMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/inventory/items/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to archive item')
    },
    onSuccess: () => {
      toast.success('Item archived')
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
    },
    onError: () => toast.error('Failed to archive item'),
  })

  // ── Bulk mutations ─────────────────────────────────────────────────────────

  const addToPOMutation = useMutation({
    mutationFn: async (ids: string[]) => {
      const res = await fetch('/api/inventory/stock-alerts/add-to-po', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ item_ids: ids }),
      })
      if (!res.ok) {
        const body = await res.json().catch(() => ({})) as { error?: string }
        throw new Error(body.error ?? 'Failed to create purchase orders')
      }
      return res.json() as Promise<{ po_ids: string[] }>
    },
    onSuccess: ({ po_ids }) => {
      toast.success(`Created ${po_ids.length} draft PO${po_ids.length === 1 ? '' : 's'}`)
      setSelectedIds(new Set())
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
    },
    onError: (err) =>
      toast.error(err instanceof Error ? err.message : 'Failed to create purchase orders'),
  })

  const bulkArchiveMutation = useMutation({
    mutationFn: async (ids: string[]) => {
      // Archive each item — no batch endpoint exists; loop sequentially
      const results = await Promise.allSettled(
        ids.map((id) => fetch(`/api/inventory/items/${id}`, { method: 'DELETE' })),
      )
      const failed = results.filter((r) => r.status === 'rejected').length
      if (failed > 0) throw new Error(`${failed} item${failed === 1 ? '' : 's'} could not be archived`)
    },
    onSuccess: () => {
      const count = selectedIds.size
      toast.success(`${count} item${count === 1 ? '' : 's'} archived`)
      setSelectedIds(new Set())
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
    },
    onError: (err) =>
      toast.error(err instanceof Error ? err.message : 'Some items could not be archived'),
  })

  const hasActiveFilters = search !== '' || categoryFilter !== 'all' || stockFilter !== 'all'
  const selectionCount = selectedIds.size

  return (
    <>
      {/* Filters — always visible */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-1 items-center gap-2">
          <div className="relative flex-1 max-w-xs">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search items..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8 h-8"
            />
          </div>
          <Select value={categoryFilter} onValueChange={(v) => { if (v !== null) setCategoryFilter(v) }}>
            <SelectTrigger className="h-8 w-32">
              <SlidersHorizontal className="mr-1.5 h-3.5 w-3.5 text-muted-foreground" />
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              <SelectItem value="ink">Ink</SelectItem>
              <SelectItem value="needle">Needle</SelectItem>
              <SelectItem value="supply">Supply</SelectItem>
              <SelectItem value="aftercare">Aftercare</SelectItem>
              <SelectItem value="equipment">Equipment</SelectItem>
              <SelectItem value="apparel">Apparel</SelectItem>
              <SelectItem value="other">Other</SelectItem>
            </SelectContent>
          </Select>
          <Select value={stockFilter} onValueChange={(v) => { if (v !== null) setStockFilter(v) }}>
            <SelectTrigger className="h-8 w-32">
              <SelectValue placeholder="Stock" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Stock</SelectItem>
              <SelectItem value="low">Low Stock</SelectItem>
              <SelectItem value="out">Out of Stock</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <Button
          size="sm"
          onClick={() => { setEditItem(null); setDrawerOpen(true) }}
          className="shrink-0"
        >
          <Plus className="mr-1.5 h-4 w-4" />
          Add Item
        </Button>
      </div>

      <DataState
        data={data}
        isLoading={isLoading}
        isError={!!error}
        error={error instanceof Error ? error : null}
        loadingSlot={<TableSkeleton rows={6} />}
        emptySlot={
          hasActiveFilters ? (
            <EmptyState
              icon={Package}
              title="No items match your filters"
              description="Try adjusting your search or category filters."
              variant="no-results"
              cta={{ label: 'Clear filters', onClick: () => { setSearch(''); setCategoryFilter('all'); setStockFilter('all') } }}
            />
          ) : (
            <EmptyState
              icon={Package}
              title="No inventory items yet"
              description="Add your first inventory item to start tracking stock and COGS."
              variant="first-time"
              cta={{ label: 'Add Item', onClick: () => { setEditItem(null); setDrawerOpen(true) } }}
            />
          )
        }
      >
        {(items) => {
          const filtered = items.filter((item) => {
            if (!search) return true
            const q = search.toLowerCase()
            return (
              item.name.toLowerCase().includes(q) ||
              item.sku?.toLowerCase().includes(q) ||
              item.brand?.toLowerCase().includes(q)
            )
          })

          if (filtered.length === 0) {
            return (
              <EmptyState
                icon={Package}
                title="No items match your search"
                description="Try a different search term."
                variant="no-results"
              />
            )
          }

          const allPageSelected =
            filtered.length > 0 && filtered.every((item) => selectedIds.has(item.id))
          const somePageSelected =
            filtered.some((item) => selectedIds.has(item.id)) && !allPageSelected

          if (viewMode === 'cards') {
            return (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {filtered.map((item) => (
                  <div
                    key={item.id}
                    className="group relative rounded-xl border border-border/60 bg-card p-4 space-y-3 hover:border-primary/30 hover:shadow-card-hover transition-all duration-150"
                  >
                    {/* Row checkbox in card mode */}
                    <div className="absolute top-3 left-3">
                      <Checkbox
                        checked={selectedIds.has(item.id)}
                        onCheckedChange={() => setSelectedIds((prev) => toggleId(prev, item.id))}
                        aria-label={`Select ${item.name}`}
                        className="opacity-0 group-hover:opacity-100 data-[state=checked]:opacity-100"
                      />
                    </div>

                    <div className="flex items-start justify-between gap-2 pl-6">
                      <div className="min-w-0">
                        <p className="font-medium text-sm truncate">{item.name}</p>
                        {item.sku && (
                          <p className="text-[11px] font-mono text-muted-foreground truncate">{item.sku}</p>
                        )}
                      </div>
                      <DropdownMenu>
                        <DropdownMenuTrigger render={
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 shrink-0 opacity-0 group-hover:opacity-100"
                          >
                            <MoreHorizontal className="h-4 w-4" />
                          </Button>
                        } />
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => { setEditItem(item); setDrawerOpen(true) }}>
                            <Edit className="mr-2 h-4 w-4" />
                            Edit
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => setAdjustItem(item)}>
                            <Minus className="mr-2 h-4 w-4" />
                            Adjust Stock
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            className="text-destructive focus:text-destructive"
                            onClick={() => archiveMutation.mutate(item.id)}
                          >
                            <Archive className="mr-2 h-4 w-4" />
                            Archive
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </div>

                    <div className="flex items-center gap-2 flex-wrap">
                      <CategoryBadge category={item.category} />
                      <StockLevelBadge current={Number(item.current_stock)} min={Number(item.min_threshold)} />
                    </div>

                    <div className="flex items-center justify-between text-xs text-muted-foreground">
                      <span>{item.brand ?? 'No brand'}</span>
                      <span className="tabular-nums font-medium text-foreground">
                        {formatCurrency(item.cost_per_unit_cents)}/unit
                      </span>
                    </div>

                    {item.suppliers?.name && (
                      <p className="text-[11px] text-muted-foreground truncate">{item.suppliers.name}</p>
                    )}
                  </div>
                ))}
              </div>
            )
          }

          return (
            <div className="rounded-lg border border-border overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow className="bg-muted/30 hover:bg-muted/30">
                    {/* Select-all checkbox */}
                    <TableHead className="w-10 pl-3">
                      <Checkbox
                        checked={allPageSelected ? true : somePageSelected ? 'indeterminate' : false}
                        onCheckedChange={(checked) => {
                          if (checked) {
                            setSelectedIds((prev) => {
                              const next = new Set(prev)
                              filtered.forEach((item) => next.add(item.id))
                              return next
                            })
                          } else {
                            setSelectedIds((prev) => {
                              const next = new Set(prev)
                              filtered.forEach((item) => next.delete(item.id))
                              return next
                            })
                          }
                        }}
                        aria-label="Select all visible items"
                      />
                    </TableHead>
                    <TableHead className="text-xs">Name</TableHead>
                    <TableHead className="text-xs">Category</TableHead>
                    <TableHead className="text-xs">Brand</TableHead>
                    <TableHead className="text-xs text-right">Stock</TableHead>
                    <TableHead className="text-xs text-right">Cost/Unit</TableHead>
                    <TableHead className="text-xs">Supplier</TableHead>
                    <TableHead className="w-10" />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filtered.map((item) => (
                    <TableRow
                      key={item.id}
                      className="group"
                      data-selected={selectedIds.has(item.id)}
                    >
                      <TableCell className="pl-3">
                        <Checkbox
                          checked={selectedIds.has(item.id)}
                          onCheckedChange={() => setSelectedIds((prev) => toggleId(prev, item.id))}
                          aria-label={`Select ${item.name}`}
                        />
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col gap-0.5">
                          <span className="text-sm font-medium">{item.name}</span>
                          {item.sku && (
                            <span className="text-[11px] font-mono text-muted-foreground">
                              {item.sku}
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <CategoryBadge category={item.category} />
                      </TableCell>
                      <TableCell>
                        <span className="text-sm text-muted-foreground">
                          {item.brand ?? '—'}
                        </span>
                      </TableCell>
                      <TableCell className="text-right">
                        <StockLevelBadge current={Number(item.current_stock)} min={Number(item.min_threshold)} />
                      </TableCell>
                      <TableCell className="text-right text-sm tabular-nums">
                        {formatCurrency(item.cost_per_unit_cents)}
                      </TableCell>
                      <TableCell>
                        <span className="text-sm text-muted-foreground">
                          {item.suppliers?.name ?? '—'}
                        </span>
                      </TableCell>
                      <TableCell>
                        <DropdownMenu>
                          <DropdownMenuTrigger render={
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-7 w-7 opacity-0 group-hover:opacity-100"
                            >
                              <MoreHorizontal className="h-4 w-4" />
                            </Button>
                          } />
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem
                              onClick={() => { setEditItem(item); setDrawerOpen(true) }}
                            >
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => setAdjustItem(item)}
                            >
                              <Minus className="mr-2 h-4 w-4" />
                              Adjust Stock
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              className="text-destructive focus:text-destructive"
                              onClick={() => archiveMutation.mutate(item.id)}
                            >
                              <Archive className="mr-2 h-4 w-4" />
                              Archive
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )
        }}
      </DataState>

      {/* ── Sticky bulk-action bar ─────────────────────────────────────────── */}
      {selectionCount >= 1 && (
        <div
          className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-2 rounded-lg border border-border bg-card px-4 py-2.5 shadow-soft-md"
          role="toolbar"
          aria-label="Bulk actions"
        >
          <span className="mr-2 text-sm text-stone-brand tabular-nums">
            {selectionCount} selected
          </span>

          {/* Add to PO */}
          <Button
            size="sm"
            disabled={addToPOMutation.isPending}
            onClick={() => addToPOMutation.mutate(Array.from(selectedIds))}
          >
            <ShoppingCart className="mr-1.5 h-3.5 w-3.5" />
            Add {selectionCount} to PO
          </Button>

          {/* Bulk thresholds */}
          <Button
            size="sm"
            variant="outline"
            onClick={() => setBulkThresholdsOpen(true)}
          >
            <Settings2 className="mr-1.5 h-3.5 w-3.5" />
            Bulk thresholds
          </Button>

          {/* Archive */}
          <Button
            size="sm"
            variant="outline"
            className="border-destructive text-destructive hover:bg-destructive/10"
            disabled={bulkArchiveMutation.isPending}
            onClick={() => setArchiveConfirmOpen(true)}
          >
            <Archive className="mr-1.5 h-3.5 w-3.5" />
            Archive
          </Button>

          {/* Clear */}
          <Button
            size="sm"
            variant="ghost"
            className="text-stone-brand hover:text-foreground"
            onClick={() => setSelectedIds(new Set())}
          >
            <X className="mr-1.5 h-3.5 w-3.5" />
            Clear
          </Button>
        </div>
      )}

      {/* ── Sub-components ────────────────────────────────────────────────── */}

      <ItemForm
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        item={editItem}
        onSuccess={() => {
          void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
        }}
      />

      {adjustItem && (
        <StockAdjustmentModal
          open={true}
          onOpenChange={(open) => { if (!open) setAdjustItem(null) }}
          item={adjustItem}
          onSuccess={() => {
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.movements() })
          }}
        />
      )}

      <BulkThresholdsDrawer
        open={bulkThresholdsOpen}
        onOpenChange={setBulkThresholdsOpen}
        mode="manual"
      />

      {/* Archive confirmation dialog */}
      <AlertDialog open={archiveConfirmOpen} onOpenChange={setArchiveConfirmOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Archive {selectionCount} item{selectionCount === 1 ? '' : 's'}?
            </AlertDialogTitle>
            <AlertDialogDescription>
              {selectionCount === 1
                ? 'This item will be hidden from stock views. Data is preserved and can be restored.'
                : `These ${selectionCount} items will be hidden from stock views. Data is preserved and can be restored.`}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => {
                setArchiveConfirmOpen(false)
                bulkArchiveMutation.mutate(Array.from(selectedIds))
              }}
            >
              Archive
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

